children.input:
{
  "project_id": "14f09167c1e64988a435",
  "name": "workspace_scoped_notes",
  "query": "create schema if not exists private;

create table public.workspaces (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(trim(name)) between 1 and 200),
  owner_id uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.workspace_members (
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null default 'member' check (role in ('owner', 'member')),
  created_at timestamptz not null default now(),
  primary key (workspace_id, user_id)
);

create table public.notes (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  author_id uuid not null references auth.users(id) on delete restrict,
  title text not null default '' check (char_length(title) <= 500),
  body text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index workspace_members_user_workspace_idx
  on public.workspace_members (user_id, workspace_id);
create index notes_workspace_created_at_idx
  on public.notes (workspace_id, created_at desc);

alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;
alter table public.notes enable row level security;

create policy "workspace owners and members can view workspaces"
on public.workspaces for select to authenticated
using (
  owner_id = (select auth.uid())
  or id in (
    select workspace_id from public.workspace_members
    where user_id = (select auth.uid())
  )
);

create policy "users can create their own workspaces"
on public.workspaces for insert to authenticated
with check (owner_id = (select auth.uid()));

create policy "only owners can update workspaces"
on public.workspaces for update to authenticated
using (owner_id = (select auth.uid()))
with check (owner_id = (select auth.uid()));

create policy "only owners can delete workspaces"
on public.workspaces for delete to authenticated
using (owner_id = (select auth.uid()));

create policy "members can view their memberships and owners can manage them"
on public.workspace_members for select to authenticated
using (
  user_id = (select auth.uid())
  or workspace_id in (
    select id from public.workspaces
    where owner_id = (select auth.uid())
  )
);

create policy "only workspace owners can add members"
on public.workspace_members for insert to authenticated
with check (
  workspace_id in (
    select id from public.workspaces
    where owner_id = (select auth.uid())
  )
);

create policy "only workspace owners can update memberships"
on public.workspace_members for update to authenticated
using (
  workspace_id in (
    select id from public.workspaces
    where owner_id = (select auth.uid())
  )
)
with check (
  workspace_id in (
    select id from public.workspaces
    where owner_id = (select auth.uid())
  )
);

create policy "only workspace owners can remove members"
on public.workspace_members for delete to authenticated
using (
  workspace_id in (
    select id from public.workspaces
    where owner_id = (select auth.uid())
  )
);

create policy "workspace members can view notes"
on public.notes for select to authenticated
using (
  workspace_id in (
    select workspace_id from public.workspace_members
    where user_id = (select auth.uid())
  )
  or workspace_id in (
    select id from public.workspaces
    where owner_id = (select auth.uid())
  )
);

create policy "workspace members can create notes in their workspace"
on public.notes for insert to authenticated
with check (
  author_id = (select auth.uid())
  and (
    workspace_id in (
      select workspace_id from public.workspace_members
      where user_id = (select auth.uid())
    )
    or workspace_id in (
      select id from public.workspaces
      where owner_id = (select auth.uid())
    )
  )
);

create policy "authors can update their own workspace notes"
on public.notes for update to authenticated
using (
  author_id = (select auth.uid())
  and (
    workspace_id in (
      select workspace_id from public.workspace_members
      where user_id = (select auth.uid())
    )
    or workspace_id in (
      select id from public.workspaces
      where owner_id = (select auth.uid())
    )
  )
)
with check (
  author_id = (select auth.uid())
  and (
    workspace_id in (
      select workspace_id from public.workspace_members
      where user_id = (select auth.uid())
    )
    or workspace_id in (
      select id from public.workspaces
      where owner_id = (select auth.uid())
    )
  )
);

create policy "authors can delete their own workspace notes"
on public.notes for delete to authenticated
using (
  author_id = (select auth.uid())
  and (
    workspace_id in (
      select workspace_id from public.workspace_members
      where user_id = (select auth.uid())
    )
    or workspace_id in (
      select id from public.workspaces
      where owner_id = (select auth.uid())
    )
  )
);

create function private.prevent_note_workspace_change()
returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if new.workspace_id is distinct from old.workspace_id then
    raise exception 'A note cannot be moved to another workspace';
  end if;
  new.updated_at = now();
  return new;
end;
$$;

create trigger prevent_note_workspace_change
before update on public.notes
for each row execute function private.prevent_note_workspace_change();

revoke all on function private.prevent_note_workspace_change() from public;

grant usage on schema public to authenticated;
grant select, insert, update, delete on public.workspaces, public.workspace_members, public.notes to authenticated;"
}

