{
  "project_id": "14f09167c1e64988a435",
  "name": "replace_recursive_workspace_policies",
  "query": "create or replace function private.is_workspace_owner(target_workspace_id uuid) returns boolean language sql stable security definer set search_path = pg_catalog as $$ select exists (select 1 from public.workspaces w where w.id = target_workspace_id and w.owner_id = (select auth.uid())); $$;
create or replace function private.is_workspace_member(target_workspace_id uuid) returns boolean language sql stable security definer set search_path = pg_catalog as $$ select exists (select 1 from public.workspace_members wm where wm.workspace_id = target_workspace_id and wm.user_id = (select auth.uid())); $$;
revoke all on function private.is_workspace_owner(uuid) from public;
revoke all on function private.is_workspace_member(uuid) from public;
grant usage on schema private to authenticated;
grant execute on function private.is_workspace_owner(uuid), private.is_workspace_member(uuid) to authenticated;
drop policy "workspace owners and members can view workspaces" on public.workspaces;
drop policy "members can view their memberships and owners can manage them" on public.workspace_members;
drop policy "only workspace owners can add members" on public.workspace_members;
drop policy "only workspace owners can update memberships" on public.workspace_members;
drop policy "only workspace owners can remove members" on public.workspace_members;
drop policy "workspace members can view notes" on public.notes;
drop policy "workspace members can create notes in their workspace" on public.notes;
drop policy "authors can update their own workspace notes" on public.notes;
drop policy "authors can delete their own workspace notes" on public.notes;
create policy "workspace owners and members can view workspaces" on public.workspaces for select to authenticated using (owner_id = (select auth.uid()) or (select private.is_workspace_member(id)));
create policy "members can view their memberships and owners can manage them" on public.workspace_members for select to authenticated using (user_id = (select auth.uid()) or (select private.is_workspace_owner(workspace_id)));
create policy "only workspace owners can add members" on public.workspace_members for insert to authenticated with check ((select private.is_workspace_owner(workspace_id)));
create policy "only workspace owners can update memberships" on public.workspace_members for update to authenticated using ((select private.is_workspace_owner(workspace_id))) with check ((select private.is_workspace_owner(workspace_id)));
create policy "only workspace owners can remove members" on public.workspace_members for delete to authenticated using ((select private.is_workspace_owner(workspace_id)));
create policy "workspace members can view notes" on public.notes for select to authenticated using ((select private.is_workspace_owner(workspace_id)) or (select private.is_workspace_member(workspace_id)));
create policy "workspace members can create notes in their workspace" on public.notes for insert to authenticated with check (author_id = (select auth.uid()) and ((select private.is_workspace_owner(workspace_id)) or (select private.is_workspace_member(workspace_id))));
create policy "authors can update their own workspace notes" on public.notes for update to authenticated using (author_id = (select auth.uid()) and ((select private.is_workspace_owner(workspace_id)) or (select private.is_workspace_member(workspace_id)))) with check (author_id = (select auth.uid()) and ((select private.is_workspace_owner(workspace_id)) or (select private.is_workspace_member(workspace_id))));
create policy "authors can delete their own workspace notes" on public.notes for delete to authenticated using (author_id = (select auth.uid()) and ((select private.is_workspace_owner(workspace_id)) or (select private.is_workspace_member(workspace_id))));"
}

